    pattern_offsets = set()
    for pr, pc in zero_positions:
        pattern_offsets.add((pr - cy, pc - cx))

    # Find 6s in input - these remain 6
    six_positions = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

