def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find background (most common color)
    color_counts = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            color_counts[v] = color_counts.get(v, 0) + 1
    bg = max(color_counts, key=color_counts.get)

    # Find special color (non-bg, non-0, non-2, appearing in grid)
    all_vals = set(color_counts.keys())
    special_color = None
    for v in all_vals:
        if v not in (bg, 0, 2):
            special_color = v
            break

    if bg is None or special_color is None:
        return grid

    # Find all 3 positions
    threes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]

    # Find all 0 positions
    zeros = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0]

    if not threes:
        return grid

    # Find "main" 3 (the one closest to or connected with 0-cluster)
    # Calculate centroid of 0s
    if zeros:
        cy, cx = sum(r for r, c in zeros) // len(zeros), sum(c for r, c in zeros) // len(zeros)
    else:
        cy, cx = 0, 0

    main_3 = None
    best_dist = float('inf')
    for tr, tc in threes:
        dist = abs(tr - cy) + abs(tc - cx)  # Manhattan distance to 0-centroid
        if dist < best_dist:
            best_dist = dist
            main_3 = (tr, tc)

    # Extract pattern relative to main_3
    pattern_offsets = []
    if main_3 and zeros:
        mr, mc = main_3
        for zr, zc in zeros:
            pattern_offsets.append((zr - mr, zc - mc))

    # Build result
    result = [row[:] for row in grid]

    # Apply transformation to each 3
    for tr, tc in threes:
        if main_3 == (tr, tc):
            result[tr][tc] = 3
        else:
            result[tr][tc] = special_color
            # Replicate pattern
            for dr, dc in pattern_offsets:
                nr, nc = tr + dr, tc + dc
                if 0 <= nr < h and 0 <= nc < w:
                    result[nr][nc] = 0

    return result
